def delete(self, key: bytes) -> bool:
    if key not in self.data:
        return False
    expired = self._is_expired(key)
    if expired and not self.is_replica:
        self._expire_if_needed(key)  # master: counts as an expiry, propagates DEL
        return False
    self._remove(key)
    return not expired

