def _check_save_rules(self) -> None:
    p = self.persistence
    if p.bgsave_in_progress or not p.dirty:
        return
    elapsed = time.time() - p.last_save_time
    for seconds, changes in self.config.save_rules:
        if elapsed >= seconds and p.dirty >= changes:
            self.start_bgsave()
            return
